import { createContext } from "svelte";
import type { TooltipHandle } from "./handle.svelte.js";

const [getHandleContext, setHandleContext] = createContext<TooltipHandle>();

export function getTooltipHandleContext<Payload = unknown>(): TooltipHandle<Payload> {
  return getHandleContext() as unknown as TooltipHandle<Payload>;
}

export function setTooltipHandleContext<Payload>(handle: TooltipHandle<Payload>): void {
  setHandleContext(handle as unknown as TooltipHandle);
}

import type { Attachment } from "svelte/attachments";
import { on } from "svelte/events";
import type { TooltipHandle } from "./handle.svelte.js";
import type { TooltipAttachmentProviderMember } from "./provider-context.svelte.js";
import { createTooltipSafePolygon, type TooltipSafePolygonSide } from "./safe-polygon.js";

const DEFAULT_OPEN_DELAY = 600;

type TriggerBindings<Payload> = {
  closeDelay: number;
  closeOnClick: boolean;
  payload: Payload | undefined;
};

type TriggerMap<Payload> = {
  add(id: string, element: HTMLElement, bindings: () => TriggerBindings<Payload>): () => void;
  containsNode(target: EventTarget | null | undefined): boolean;
};

type TooltipState<Payload> = {
  activeTriggerId: string | null;
  applyTriggerBindings(bindings: TriggerBindings<Payload>): void;
  closeOnClick: boolean;
  disableHoverablePopup: boolean;
  disabled: boolean;
  isInstantPhase: boolean;
  open: boolean;
  popupElement: HTMLElement | null;
  positionerElement: HTMLElement | null;
  setCursorPosition(x: number, y: number): void;
  setOpen(open: boolean, reason?: string, event?: Event, trigger?: HTMLElement | null): boolean;
  trackCursorAxis: "none" | "x" | "y" | "both";
  triggerElement: HTMLElement | null;
  triggerElements: TriggerMap<Payload>;
};

export type TooltipTriggerAttachmentOptions<Payload = unknown> = {
  /** ID used to register the target with the Shards tooltip handle. */
  id: string;
  /** ID of the tooltip popup that describes the target. Set this in markup too for SSR. */
  ariaDescribedBy?: string;
  closeDelay?: number;
  closeOnClick?: boolean;
  delay?: number;
  disabled?: boolean;
  payload?: Payload;
};

type ManagedAttribute =
  | "aria-describedby"
  | "data-popup-open"
  | "data-tooltip-trigger"
  | "data-trigger-disabled"
  | "id";

function restoreAttribute(
  node: HTMLElement,
  name: ManagedAttribute,
  previous: string | null,
): void {
  if (previous === null) node.removeAttribute(name);
  else node.setAttribute(name, previous);
}

/**
 * Applies Shards tooltip trigger behavior to an existing element without adding wrapper DOM.
 * The target stays owned by its Toolbar, Toggle, Select, or other behavioral primitive.
 *
 * This mirrors Shards Trigger registration, payload, focus, hover, cursor tracking, disabled,
 * click-dismissal, provider delay grouping, safe pointer transit, and state-attribute behavior
 * through its public handle. The local safe-polygon guard mirrors Shards behavior without importing
 * a private Shards module.
 */
export function createTriggerAttachment<Payload = unknown>(
  handle: TooltipHandle<Payload>,
  options: () => TooltipTriggerAttachmentOptions<Payload>,
): Attachment<HTMLElement> {
  return (node) => {
    const state = handle.state as unknown as TooltipState<Payload>;
    const provider = handle.attachmentProvider;
    const previous = {
      "aria-describedby": node.getAttribute("aria-describedby"),
      "data-popup-open": node.getAttribute("data-popup-open"),
      "data-tooltip-trigger": node.getAttribute("data-tooltip-trigger"),
      "data-trigger-disabled": node.getAttribute("data-trigger-disabled"),
      id: node.getAttribute("id"),
    } satisfies Record<ManagedAttribute, string | null>;
    node.setAttribute("data-tooltip-trigger", "");

    let openTimer: ReturnType<typeof setTimeout> | undefined;
    let closeTimer: ReturnType<typeof setTimeout> | undefined;
    let safeTransitCleanup: (() => void) | undefined;
    let pointerType = "mouse";
    let pointerFocus = false;
    const providerMember: TooltipAttachmentProviderMember = {
      close() {
        if (isActive()) state.setOpen(false, "none", undefined, node);
      },
      setInstant(value) {
        state.isInstantPhase = value;
      },
    };

    const clearOpenTimer = (): void => {
      if (openTimer !== undefined) clearTimeout(openTimer);
      openTimer = undefined;
    };
    const clearCloseTimer = (): void => {
      if (closeTimer !== undefined) clearTimeout(closeTimer);
      closeTimer = undefined;
    };
    const clearSafeTransit = (): void => {
      safeTransitCleanup?.();
      safeTransitCleanup = undefined;
    };
    const current = (): Required<
      Pick<TooltipTriggerAttachmentOptions<Payload>, "closeDelay" | "closeOnClick" | "delay">
    > &
      TooltipTriggerAttachmentOptions<Payload> => ({
      closeDelay: 0,
      closeOnClick: true,
      delay: DEFAULT_OPEN_DELAY,
      ...options(),
    });
    const isDisabled = (): boolean => current().disabled === true || state.disabled;
    const isActive = (): boolean => state.activeTriggerId === current().id;

    const applyBindings = (): void => {
      const value = current();
      state.applyTriggerBindings({
        closeDelay: value.closeDelay,
        closeOnClick: value.closeOnClick,
        payload: value.payload,
      });
    };
    const open = (reason: "trigger-focus" | "trigger-hover", event: Event): void => {
      if (isDisabled()) return;
      clearCloseTimer();
      clearSafeTransit();
      applyBindings();
      state.setOpen(true, reason, event, node);
    };
    const close = (
      reason: "trigger-focus" | "trigger-hover" | "trigger-press",
      event?: Event,
    ): void => {
      if (!isActive()) return;
      state.setOpen(false, reason, event, node);
    };
    const scheduleClose = (reason: "trigger-focus" | "trigger-hover", event?: Event): void => {
      clearCloseTimer();
      const delay = provider?.getCloseDelay(options().closeDelay) ?? current().closeDelay;
      if (delay === 0) close(reason, event);
      else closeTimer = setTimeout(() => close(reason, event), delay);
    };

    const getPopupSide = (popup: HTMLElement): TooltipSafePolygonSide => {
      const positioner = state.positionerElement ?? popup.closest<HTMLElement>("[data-side]");
      const side = positioner?.dataset.side;
      if (side === "bottom" || side === "left" || side === "right" || side === "top") return side;

      const referenceRect = node.getBoundingClientRect();
      const popupRect = popup.getBoundingClientRect();
      const horizontalDistance = Math.abs(
        popupRect.left + popupRect.width / 2 - (referenceRect.left + referenceRect.width / 2),
      );
      const verticalDistance = Math.abs(
        popupRect.top + popupRect.height / 2 - (referenceRect.top + referenceRect.height / 2),
      );
      if (horizontalDistance > verticalDistance) {
        return popupRect.left >= referenceRect.right ? "right" : "left";
      }
      return popupRect.top >= referenceRect.bottom ? "bottom" : "top";
    };

    const onFocus = (event: FocusEvent): void => {
      clearOpenTimer();
      if (pointerFocus) return;
      open("trigger-focus", event);
    };
    const onBlur = (event: FocusEvent): void => {
      clearOpenTimer();
      clearCloseTimer();
      closeTimer = setTimeout(() => {
        const active = node.ownerDocument.activeElement;
        if (node.contains(active) || state.popupElement?.contains(active)) return;
        if (node.matches(":hover")) return;
        close("trigger-focus", event);
      });
    };
    const onPointerDown = (event: PointerEvent): void => {
      pointerType = event.pointerType;
      pointerFocus = true;
      queueMicrotask(() => {
        pointerFocus = false;
      });
      clearOpenTimer();
    };
    const onPointerEnter = (event: PointerEvent): void => {
      pointerType = event.pointerType;
      if (pointerType === "touch" || isDisabled()) return;
      clearOpenTimer();
      clearCloseTimer();
      clearSafeTransit();
      const delay = state.open ? 0 : (provider?.getOpenDelay(options().delay) ?? current().delay);
      if (delay === 0) open("trigger-hover", event);
      else openTimer = setTimeout(() => open("trigger-hover", event), delay);
    };
    const onPointerMove = (event: PointerEvent): void => {
      if (pointerType === "touch" || state.open || state.trackCursorAxis === "none") return;
      state.setCursorPosition(event.clientX, event.clientY);
    };
    const onPointerLeave = (event: PointerEvent): void => {
      clearOpenTimer();
      if (!isActive() || pointerType === "touch") return;
      clearCloseTimer();
      clearSafeTransit();

      const popup = state.popupElement;
      if (popup && event.relatedTarget instanceof Node && popup.contains(event.relatedTarget)) {
        return;
      }
      if (state.disableHoverablePopup || state.trackCursorAxis === "both" || !popup) {
        scheduleClose("trigger-hover", event);
        return;
      }

      const polygon = createTooltipSafePolygon({
        floating: popup,
        leaveX: event.clientX,
        leaveY: event.clientY,
        onClose: () => {
          clearSafeTransit();
          scheduleClose("trigger-hover", event);
        },
        onLanding: clearSafeTransit,
        reference: node,
        side: getPopupSide(popup),
      });
      const removePointerMove = on(node.ownerDocument, "pointermove", polygon.pointermove, {
        capture: true,
      });
      safeTransitCleanup = () => {
        removePointerMove();
        polygon.destroy();
      };
    };
    const onClick = (event: MouseEvent): void => {
      clearOpenTimer();
      const value = current();
      if (value.closeOnClick && state.open && isActive()) {
        close("trigger-press", event);
      }
    };

    const disposeEffects = $effect.root(() => {
      $effect(() => {
        const value = current();
        node.id = value.id;
        if (value.ariaDescribedBy) node.setAttribute("aria-describedby", value.ariaDescribedBy);
        else node.removeAttribute("aria-describedby");
        node.toggleAttribute("data-trigger-disabled", isDisabled());
        node.toggleAttribute("data-popup-open", state.open && state.activeTriggerId === value.id);
      });

      $effect(() => {
        const activeOpen = state.open && state.activeTriggerId === current().id;
        if (activeOpen) provider?.claim(providerMember);
        else {
          clearSafeTransit();
          provider?.release(providerMember);
        }
      });

      $effect(() => {
        const value = current();
        return state.triggerElements.add(value.id, node, () => ({
          closeDelay: value.closeDelay,
          closeOnClick: value.closeOnClick,
          payload: value.payload,
        }));
      });
    });

    const cleanups = [
      on(node, "focus", onFocus),
      on(node, "blur", onBlur),
      on(node, "pointerdown", onPointerDown),
      on(node, "pointerenter", onPointerEnter),
      on(node, "pointermove", onPointerMove),
      on(node, "pointerleave", onPointerLeave),
      on(node, "click", onClick),
    ];

    return () => {
      clearOpenTimer();
      clearCloseTimer();
      clearSafeTransit();
      cleanups.forEach((cleanup) => {
        cleanup();
      });
      disposeEffects();
      provider?.remove(providerMember);
      restoreAttribute(node, "id", previous.id);
      restoreAttribute(node, "aria-describedby", previous["aria-describedby"]);
      restoreAttribute(node, "data-popup-open", previous["data-popup-open"]);
      restoreAttribute(node, "data-tooltip-trigger", previous["data-tooltip-trigger"]);
      restoreAttribute(node, "data-trigger-disabled", previous["data-trigger-disabled"]);
    };
  };
}

import { Tooltip as TooltipPrimitive } from "@shardsui/svelte";
import type { TooltipAttachmentProviderContext } from "./provider-context.svelte.js";

export class TooltipHandle<Payload = unknown> extends TooltipPrimitive.Handle<Payload> {
  attachmentProvider: TooltipAttachmentProviderContext | undefined;
  popupId = $state<string | undefined>(undefined);
}

export function createTooltipHandle<Payload = unknown>(): TooltipHandle<Payload> {
  return new TooltipHandle<Payload>();
}

import { getContext, hasContext, setContext } from "svelte";

export type TooltipAttachmentProviderMember = {
  close(): void;
  setInstant(value: boolean): void;
};

export type TooltipAttachmentProviderOptions = {
  closeDelay: number | undefined;
  delay: number | undefined;
  timeout: number;
};

export type TooltipAttachmentProviderContext = {
  claim(member: TooltipAttachmentProviderMember): void;
  destroy(): void;
  getCloseDelay(localDelay: number | undefined): number;
  getOpenDelay(localDelay: number | undefined): number;
  remove(member: TooltipAttachmentProviderMember): void;
  release(member: TooltipAttachmentProviderMember): void;
};

const PROVIDER_CONTEXT = Symbol("coss-tooltip-attachment-provider");

export function createTooltipAttachmentProviderContext(
  options: () => TooltipAttachmentProviderOptions,
): TooltipAttachmentProviderContext {
  let current: TooltipAttachmentProviderMember | null = null;
  let instantWindow = false;
  let resetTimer: ReturnType<typeof setTimeout> | undefined;

  const clearResetTimer = (): void => {
    if (resetTimer !== undefined) clearTimeout(resetTimer);
    resetTimer = undefined;
  };

  const reset = (): void => {
    clearResetTimer();
    current?.setInstant(false);
    current = null;
    instantWindow = false;
  };

  return {
    claim(member) {
      clearResetTimer();
      const previous = current;
      const tookOver = previous !== null && previous !== member;
      current = member;
      instantWindow = true;
      member.setInstant(tookOver);
      if (tookOver) {
        previous.setInstant(true);
        previous.close();
      }
    },
    destroy: reset,
    getCloseDelay(localDelay) {
      return localDelay ?? options().closeDelay ?? 0;
    },
    getOpenDelay(localDelay) {
      if (current !== null || instantWindow) return 0;
      return localDelay ?? options().delay ?? 600;
    },
    remove(member) {
      if (current === member) reset();
    },
    release(member) {
      if (current !== member) return;
      member.setInstant(false);
      instantWindow = true;
      clearResetTimer();
      const timeout = options().timeout;
      if (timeout === 0) {
        reset();
        return;
      }
      resetTimer = setTimeout(reset, timeout);
    },
  };
}

export function getTooltipAttachmentProviderContext():
  | TooltipAttachmentProviderContext
  | undefined {
  return hasContext(PROVIDER_CONTEXT)
    ? getContext<TooltipAttachmentProviderContext>(PROVIDER_CONTEXT)
    : undefined;
}

export function setTooltipAttachmentProviderContext(
  context: TooltipAttachmentProviderContext,
): void {
  setContext(PROVIDER_CONTEXT, context);
}

const CURSOR_SPEED_THRESHOLD = 0.1;
const CURSOR_SPEED_THRESHOLD_SQUARED = CURSOR_SPEED_THRESHOLD * CURSOR_SPEED_THRESHOLD;
const LANDING_GRACE_MS = 40;
const POLYGON_BUFFER = 2;

export type TooltipSafePolygonSide = "bottom" | "left" | "right" | "top";

type SafePolygonOptions = {
  floating: HTMLElement;
  leaveX: number;
  leaveY: number;
  onClose: () => void;
  onLanding: () => void;
  reference: HTMLElement;
  side: TooltipSafePolygonSide;
};

type Point = readonly [x: number, y: number];

function contains(element: HTMLElement, target: EventTarget | null): boolean {
  return target instanceof Node && element.contains(target);
}

function isInsideAxisAlignedRect(
  x: number,
  y: number,
  firstX: number,
  firstY: number,
  secondX: number,
  secondY: number,
): boolean {
  return (
    x >= Math.min(firstX, secondX) &&
    x <= Math.max(firstX, secondX) &&
    y >= Math.min(firstY, secondY) &&
    y <= Math.max(firstY, secondY)
  );
}

function isInsidePolygon(x: number, y: number, points: readonly Point[]): boolean {
  let inside = false;
  for (let index = 0, previous = points.length - 1; index < points.length; previous = index++) {
    const [currentX, currentY] = points[index] ?? [0, 0];
    const [previousX, previousY] = points[previous] ?? [0, 0];
    if (
      currentY >= y !== previousY >= y &&
      x <= ((previousX - currentX) * (y - currentY)) / (previousY - currentY) + currentX
    ) {
      inside = !inside;
    }
  }
  return inside;
}

function getTrough(
  side: TooltipSafePolygonSide,
  reference: DOMRect,
  floating: DOMRect,
): readonly [number, number, number, number] {
  const overlapLeft = Math.max(reference.left, floating.left);
  const overlapRight = Math.min(reference.right, floating.right);
  const overlapTop = Math.max(reference.top, floating.top);
  const overlapBottom = Math.min(reference.bottom, floating.bottom);

  switch (side) {
    case "top":
      return [overlapLeft, floating.bottom, overlapRight, reference.top];
    case "bottom":
      return [overlapLeft, reference.bottom, overlapRight, floating.top];
    case "left":
      return [floating.right, overlapTop, reference.left, overlapBottom];
    case "right":
      return [reference.right, overlapTop, floating.left, overlapBottom];
  }
}

function getPolygon(
  side: TooltipSafePolygonSide,
  leaveX: number,
  leaveY: number,
  floating: DOMRect,
): readonly Point[] {
  switch (side) {
    case "top":
      return [
        [leaveX - POLYGON_BUFFER, leaveY + 1],
        [leaveX + POLYGON_BUFFER, leaveY + 1],
        [floating.right, floating.bottom - 1],
        [floating.left, floating.bottom - 1],
      ];
    case "bottom":
      return [
        [leaveX - POLYGON_BUFFER, leaveY - 1],
        [leaveX + POLYGON_BUFFER, leaveY - 1],
        [floating.right, floating.top + 1],
        [floating.left, floating.top + 1],
      ];
    case "left":
      return [
        [leaveX + 1, leaveY - POLYGON_BUFFER],
        [leaveX + 1, leaveY + POLYGON_BUFFER],
        [floating.right - 1, floating.bottom],
        [floating.right - 1, floating.top],
      ];
    case "right":
      return [
        [leaveX - 1, leaveY - POLYGON_BUFFER],
        [leaveX - 1, leaveY + POLYGON_BUFFER],
        [floating.left + 1, floating.bottom],
        [floating.left + 1, floating.top],
      ];
  }
}

function movedAwayFromPopup(
  side: TooltipSafePolygonSide,
  x: number,
  y: number,
  reference: DOMRect,
): boolean {
  switch (side) {
    case "top":
      return y >= reference.bottom - 1;
    case "bottom":
      return y <= reference.top + 1;
    case "left":
      return x >= reference.right - 1;
    case "right":
      return x <= reference.left + 1;
  }
}

/**
 * Guards pointer travel between an attached trigger and its Shards popup.
 * The geometry follows the public behavior of Shards' safe polygon without importing internals.
 */
export function createTooltipSafePolygon(options: SafePolygonOptions): {
  destroy(): void;
  pointermove(event: PointerEvent): void;
} {
  let lastX: number | null = null;
  let lastY: number | null = null;
  let lastCursorTime = performance.now();
  let landingTimer: ReturnType<typeof setTimeout> | undefined;
  let destroyed = false;

  const clearLandingTimer = (): void => {
    if (landingTimer !== undefined) clearTimeout(landingTimer);
    landingTimer = undefined;
  };

  const destroy = (): void => {
    destroyed = true;
    clearLandingTimer();
  };

  const close = (): void => {
    if (destroyed) return;
    destroy();
    options.onClose();
  };

  const isMovingSlowly = (x: number, y: number): boolean => {
    const currentTime = performance.now();
    const elapsed = currentTime - lastCursorTime;
    if (lastX === null || lastY === null || elapsed === 0) {
      lastX = x;
      lastY = y;
      lastCursorTime = currentTime;
      return false;
    }
    const deltaX = x - lastX;
    const deltaY = y - lastY;
    const distanceSquared = deltaX * deltaX + deltaY * deltaY;
    const thresholdSquared = elapsed * elapsed * CURSOR_SPEED_THRESHOLD_SQUARED;
    lastX = x;
    lastY = y;
    lastCursorTime = currentTime;
    return distanceSquared < thresholdSquared;
  };

  return {
    destroy,
    pointermove(event) {
      if (destroyed) return;
      clearLandingTimer();

      if (contains(options.floating, event.target)) {
        destroy();
        options.onLanding();
        return;
      }
      if (contains(options.reference, event.target)) {
        destroy();
        options.onLanding();
        return;
      }

      const { clientX, clientY } = event;
      const referenceRect = options.reference.getBoundingClientRect();
      const floatingRect = options.floating.getBoundingClientRect();

      if (movedAwayFromPopup(options.side, clientX, clientY, referenceRect)) {
        close();
        return;
      }

      const trough = getTrough(options.side, referenceRect, floatingRect);
      if (isInsideAxisAlignedRect(clientX, clientY, ...trough)) return;

      if (isMovingSlowly(clientX, clientY)) {
        close();
        return;
      }

      if (
        !isInsidePolygon(
          clientX,
          clientY,
          getPolygon(options.side, options.leaveX, options.leaveY, floatingRect),
        )
      ) {
        close();
        return;
      }

      landingTimer = setTimeout(close, LANDING_GRACE_MS);
    },
  };
}

import type { Snippet } from "svelte";
import type { HTMLButtonAttributes } from "svelte/elements";
import type { TooltipHandle } from "./handle.svelte.js";

export type TooltipTriggerState = {
  open: boolean;
};

export type TooltipRootState<Payload> = {
  payload: Payload | undefined;
};

export type TooltipRootProps<Payload = unknown> = {
  children?: Snippet<[TooltipRootState<Payload>]>;
  defaultOpen?: boolean;
  disableHoverablePopup?: boolean;
  disabled?: boolean;
  handle?: TooltipHandle<Payload>;
  onOpenChange?: (open: boolean) => void;
  onOpenChangeComplete?: (open: boolean) => void;
  open?: boolean | undefined;
  trackCursorAxis?: "none" | "x" | "y" | "both";
  triggerId?: string | null;
};

export type TooltipTriggerProps<Payload = unknown> = Omit<
  HTMLButtonAttributes,
  "children" | "id"
> & {
  as?: keyof HTMLElementTagNameMap;
  children?: Snippet<[TooltipTriggerState]>;
  closeDelay?: number;
  closeOnClick?: boolean;
  delay?: number;
  disabled?: boolean;
  handle?: TooltipHandle<Payload>;
  id?: string;
  payload?: Payload;
  ref?: HTMLElement | null;
};

import { Tooltip as TooltipPrimitive } from "@shardsui/svelte";

export type { TooltipTriggerAttachmentOptions } from "./create-trigger-attachment.svelte.js";
export { createTriggerAttachment } from "./create-trigger-attachment.svelte.js";
export {
  createTooltipHandle as TooltipCreateHandle,
  TooltipHandle as Handle,
} from "./handle.svelte.js";
export type {
  TooltipAttachmentProviderContext,
  TooltipAttachmentProviderMember,
  TooltipAttachmentProviderOptions,
} from "./provider-context.svelte.js";
export type {
  TooltipRootProps,
  TooltipRootState,
  TooltipTriggerProps,
  TooltipTriggerState,
} from "./tooltip.types.js";
export type { TooltipPopupProps, TooltipPortalProps } from "./tooltip-popup.svelte";
export {
  default as Content,
  default as Popup,
  default as TooltipContent,
  default as TooltipPopup,
} from "./tooltip-popup.svelte";
export type { TooltipProviderProps } from "./tooltip-provider.svelte";
export { default as Provider, default as TooltipProvider } from "./tooltip-provider.svelte";
export { default as Root, default as Tooltip, default as TooltipRoot } from "./tooltip-root.svelte";
export { default as TooltipTrigger, default as Trigger } from "./tooltip-trigger.svelte";
export { TooltipPrimitive };
